  const locationsByItem={shell:'SUP-SM',lid:'SUP-BP',sensor:'SUP-NC',base:'SUP-MO',seal:'SUP-AS',straw:'SUP-CC',strawSensor:'SUP-NC'};
  const nameOf=id=>product(id)?.name||component(id)?.name||id;
  const allItems=()=>[...data.products,...data.components];
