  const isProduct=id=>data.products.some(x=>x.id===id);
  const componentCost=id=>{const rows=(data.inventory||[]).filter(r=>r.itemId===id),qty=rows.reduce((n,r)=>n+Number(r.onHand||0),0),value=rows.reduce((n,r)=>n+Number(r.onHand||0)*Number(r.avgCost??component(id)?.cost??0),0);return qty?value/qty:Number(component(id)?.cost||0);};
