  const rowFor=(itemId,locationId,create=true)=>{let r=data.inventory.find(x=>x.itemId===itemId&&x.locationId===locationId);if(!r&&create){r={itemId,locationId,onHand:0,avgCost:isProduct(itemId)?productCost(item(itemId)):(component(itemId)?.cost||0)};data.inventory.push(r)}return r};
