    for(const s of data.suppliers){const targetId=remap[s.name];if(!targetId)continue;const oldId=s.id,seed=supplierSeed.find(x=>x.id===targetId);if(!seed)continue;Object.assign(s,structuredClone(seed));for(const po of data.purchaseOrders)if(po.supplierId===oldId)po.supplierId=targetId;}
