      {ref:'WO-1047',product:'P24',locationId:'RNO',qtyStarted:36,qtyGood:35,qtyScrap:1,rework:0,reason:'Cosmetic finish',status:'Completed',startedAt:'2026-10-14T09:00',finishedAt:'2026-10-14T13:15'},
      {ref:'WO-1051',product:'PGG',locationId:'AUS',qtyStarted:25,qtyGood:24,qtyScrap:1,rework:0,reason:'LED test failure',status:'Completed',startedAt:'2026-10-21T10:00',finishedAt:'2026-10-21T12:45'}
