  initData();
  const baseSave=save;
  let supabaseClient=null,authUser=null,supabaseChannel=null,syncTimer=null,remoteApplying=false,scanStream=null,scanLoop=0;
  const dataChannel='BroadcastChannel'in window?new BroadcastChannel('watagachi-erp'):null;
  function saveSnapshot(){baseSave();if(dataChannel)dataChannel.postMessage({type:'state',state:data});if(supabaseClient&&authUser&&!remoteApplying){clearTimeout(syncTimer);syncTimer=setTimeout(writeSnapshot,300);}}
  save=saveSnapshot;
  function applyState(next){if(!next||!next.products||!next.components)return;remoteApplying=true;for(const k of Object.keys(data))delete data[k];Object.assign(data,JSON.parse(JSON.stringify(next)));initData();baseSave();remoteApplying=false;renderAll();}
