  if(dataChannel)dataChannel.onmessage=e=>{if(e.data?.type==='state')applyState(e.data.state)};
  const originalFinanceRender=renderFinance;renderFinance=function(){originalFinanceRender();const t=$('#valuationTable');if(t){const rows=allItems().map(i=>{const stockRows=data.inventory.filter(r=>r.itemId===i.id),qty=stockRows.reduce((n,r)=>n+Number(r.onHand||0),0),value=stockRows.reduce((n,r)=>n+Number(r.onHand||0)*Number(r.avgCost||0),0),avg=qty?value/qty:0;return `<tr><td><strong>${esc(i.name)}</strong><div class="small-muted">${esc(i.sku)} · ${isProduct(i.id)?'Finished goods':'Component'}</div></td><td>${qty}</td><td>${money2(avg)}</td><td><strong>${money2(value)}</strong></td></tr>`;}).join('');t.innerHTML=`<table class="table"><thead><tr><th>Item</th><th>On hand</th><th>Weighted avg. cost</th><th>Inventory value</th></tr></thead><tbody>${rows}<tr><td colspan="3"><strong>Total inventory value</strong></td><td><strong>${money2(getFinancials().invValue)}</strong></td></tr></tbody></table>`;}};
  const baseRenderAll=renderAll;renderAll=function(){baseRenderAll();renderModules();baseSave();};
  const baseShowView=showView;showView=function(v){baseShowView(v);const names={dashboard:'Dashboard',mrp:'MRP planning',finance:'Financials',bom:'Items & BOM',pos:'Point of sale',inventory:'Inventory & barcodes',orders:'Sales orders',returns:'Returns & exchanges','purchase-orders':'Purchase orders',suppliers:'Supplier scorecards',procurement:'Suppliers & POs',production:'Production orders',reports:'Manager reports',customer:'Pickup portal',settings:'Database & logins'};$('#crumbTitle').textContent=names[v]||v;renderModule(v);};
  function locationsHtml(selected){return data.locations.map(l=>`<option value="${esc(l.id)}" ${l.id===selected?'selected':''}>${esc(l.name)}</option>`).join('');}
  function productOptions(selected,withBlank=false){return `${withBlank?'<option value="">No exchange</option>':''}`+data.products.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${esc(p.sku)}</option>`).join('');}
  function itemOptions(selected){return allItems().map(i=>`<option value="${esc(i.id)}" ${i.id===selected?'selected':''}>${esc(i.name)} · ${esc(i.sku)}</option>`).join('');}
  function fillSelectors(){
    $$('.locationSelect').forEach(s=>{const val=s.value||'SLC';s.innerHTML=locationsHtml(val);});
    $$('.productSelect').forEach(s=>{const val=s.value;s.innerHTML=productOptions(val,s.name==='exchange');});
    $$('.itemSelect').forEach(s=>{const val=s.value;s.innerHTML=itemOptions(val);});
    ['posProduct','adjustItem','poItem'].forEach(id=>{const s=$('#'+id);if(s){const val=s.value;s.innerHTML=id==='poItem'?data.components.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(c.sku)}</option>`).join(''):id==='posProduct'?productOptions(val):itemOptions(val);if(val)s.value=val;}});
    const supplierSelect=$('#poSupplier');if(supplierSelect){const val=supplierSelect.value;supplierSelect.innerHTML=data.suppliers.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');if(val)supplierSelect.value=val;}
    const ret=$('#returnOrder');if(ret){const val=ret.value;ret.innerHTML='<option value="">Choose order</option>'+data.orders.map(o=>`<option value="${esc(o.ref)}">${esc(o.ref)} · ${esc(o.customer||'Customer')}</option>`).join('');if(val)ret.value=val;}
    const filter=$('#inventoryLocationFilter');if(filter){const val=filter.value||'all';filter.innerHTML='<option value="all">All locations</option>'+data.locations.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('');filter.value=val;}
  }
  function renderModule(view){if(view==='dashboard')renderDashboard();if(view==='pos')renderPOS();if(view==='inventory')renderInventory();if(view==='orders')renderSalesOrders();if(view==='production')renderProduction();if(view==='returns')renderReturns();if(view==='procurement'||view==='purchase-orders'||view==='suppliers')renderProcurement();if(view==='reports')renderReports();if(view==='customer')renderCustomer();if(view==='settings')renderSettings();}
  function ensureNewInventoryRows(){linesNormalize();for(const i of allItems()){if(!data.inventory.some(r=>r.itemId===i.id)){const seed=Number(i.onhand)||0;data.inventory.push({itemId:i.id,locationId:'SLC',onHand:seed,avgCost:isProduct(i.id)?productCost(i):(i.cost||0)});}for(const l of data.locations)rowFor(i.id,l.id);}}
  function renderModules(){ensureNewInventoryRows();refreshAggregates();fillSelectors();renderDashboard();renderPOS();renderInventory();renderSalesOrders();renderProduction();renderReturns();renderProcurement();renderReports();renderCustomer();renderSettings();}
  let cart=[];
  function addCart(id,qty=1){const p=product(id);if(!p)return;const row=cart.find(x=>x.product===id);row?row.qty+=Number(qty):cart.push({product:id,qty:Number(qty)});renderPOS();}
  function renderPOS(){fillSelectors();const table=$('#posCartTable');if(!table)return;const subtotal=cart.reduce((n,l)=>n+(product(l.product)?.price||0)*l.qty,0),discount=Number($('#posDiscount')?.value||0),tax=Number($('#posTax')?.value||data.settings.taxRate||0),after=subtotal*(1-discount/100);table.innerHTML=cart.length?`<table class="table"><thead><tr><th>Product</th><th>Qty</th><th>Price</th><th>Line total</th><th></th></tr></thead><tbody>${cart.map((l,i)=>{const p=product(l.product);return `<tr><td><strong>${esc(p?.name)}</strong><div class="small-muted">${esc(p?.sku)}</div></td><td><input class="inline-input pos-line-qty" data-i="${i}" type="number" min="1" value="${l.qty}"></td><td>${money2(p?.price||0)}</td><td>${money2((p?.price||0)*l.qty)}</td><td><button class="row-button" data-remove-cart="${i}">Remove</button></td></tr>`}).join('')}</tbody><tfoot><tr><td colspan="3">Subtotal</td><td>${money2(subtotal)}</td></tr><tr><td colspan="3">Discount · ${discount}%</td><td>−${money2(subtotal*discount/100)}</td></tr><tr><td colspan="3">Tax · ${tax}%</td><td>${money2(after*tax/100)}</td></tr><tr><td colspan="3"><strong>Total</strong></td><td><strong>${money2(after*(1+tax/100))}</strong></td></tr></tfoot></table>`:'<div class="empty">Scan or add a product to begin.</div>';}
  function findBarcode(code){return allItems().find(x=>String(itemBarcode(x)).trim()===String(code).trim());}
  function scanPos(code){const x=findBarcode(code);if(!x){toast('Barcode not found in the item catalog.');return;}if(!isProduct(x.id)){toast(`${x.name} is a component; scan a finished product in POS.`);return;}addCart(x.id,1);$('#posScan').value='';}
  function scanInventory(code){const x=findBarcode(code);if(!x){toast('Barcode not found in the item catalog.');return;}$('#adjustItem').value=x.id;toast(`Selected ${x.name} for inventory receive or adjustment.`);}
  function setStock(itemId,locationId,delta,reason='Adjustment',mode='delta',incomingCost=null){
    const r=rowFor(itemId,locationId);const before=Number(r.onHand)||0,oldCost=Number(r.avgCost)||Number(isProduct(itemId)?productCost(item(itemId)):component(itemId)?.cost)||0;const after=mode==='set'?Math.max(0,Number(delta)||0):Math.max(0,before+Number(delta||0));const actual=after-before;if(actual>0&&incomingCost!==null&&after>0)r.avgCost=((before*oldCost)+(actual*Number(incomingCost)))/after;else if(!r.avgCost)r.avgCost=oldCost;r.onHand=after;data.stockHistory.unshift({date:todayISO(),itemId,locationId,delta:actual,before,after,reason,unitCost:incomingCost});refreshAggregates();return actual;
  }
  const reservedAt=(itemId,locId)=>data.inventory.filter(r=>r.itemId===itemId&&r.locationId===locId).reduce((n,r)=>n+Number(r.committed||0),0);
  function canConsumeBom(p,qty,locId){return Object.entries(p?.bom||{}).every(([cid,per])=>availableAt(cid,locId)>=Number(per||0)*Number(qty||0));}
  function consumeBom(p,qty,locId,reason='BOM consumption'){for(const[cid,per]of Object.entries(p?.bom||{})){const needed=Number(per||0)*Number(qty||0);if(needed>0)setStock(cid,locId,-needed,reason);}}
  const quarantineAt=(itemId,locId)=>data.returns.filter(r=>r.status==='Inspection'&&r.disposition==='Quarantined'&&r.product===itemId&&(r.locationId||'SLC')===locId).reduce((n,r)=>n+Number(r.qty||0),0);
