  async function writeSnapshot(){if(!supabaseClient||!authUser||remoteApplying)return;const {error}=await supabaseClient.from('erp_state').upsert({id:'watagachi',payload:data,updated_by:authUser.id},{onConflict:'id'});if(error){$('#supabaseStatus').textContent='Shared save failed: '+error.message;}}
  function applyRemoteSnapshot(payload){if(!payload)return;applyState(payload);}
  async function loadSharedState(){if(!supabaseClient||!authUser)return;const {data:record,error}=await supabaseClient.from('erp_state').select('payload,updated_by').eq('id','watagachi').maybeSingle();if(error){$('#supabaseStatus').textContent='Could not read shared data: '+error.message;return;}if(record?.payload){applyRemoteSnapshot(record.payload);}else await writeSnapshot();if(supabaseChannel)supabaseClient.removeChannel(supabaseChannel);supabaseChannel=supabaseClient.channel('watagachi-erp-state').on('postgres_changes',{event:'*',schema:'public',table:'erp_state',filter:'id=eq.watagachi'},payload=>{if(payload.new?.updated_by!==authUser?.id)applyRemoteSnapshot(payload.new?.payload);}).subscribe();renderSettingsAfterAuth();}
  async function connectSupabase(url,key){if(!window.supabase?.createClient){$('#supabaseStatus').textContent='Supabase client did not load. Check your connection and refresh.';return;}try{supabaseClient=window.supabase.createClient(url,key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data:s}=await supabaseClient.auth.getSession();authUser=s.session?.user||null;supabaseClient.auth.onAuthStateChange((_event,session)=>{authUser=session?.user||null;renderSettingsAfterAuth();if(authUser)loadSharedState();});if(authUser)await loadSharedState();renderSettingsAfterAuth();$('#supabaseStatus').textContent=authUser?`Connected and signed in as ${authUser.email}`:'Connected · sign in to load shared records.';}catch(err){$('#supabaseStatus').textContent='Connection failed: '+err.message;}}
