  const origFinanceChart=renderFinanceChart;renderFinanceChart=function(){const months=[];const now=new Date();for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);months.push({key:d.toISOString().slice(0,7),label:d.toLocaleDateString('en-US',{month:'short'})});}const vals=months.map(m=>data.transactions.filter(t=>t.date.slice(0,7)===m.key).reduce((n,t)=>n+t.qty*t.price,0));const max=Math.max(1,...vals);const W=500,H=170,px=28,py=12,gw=W-px*2,gh=H-py*2,pts=vals.map((v,i)=>[px+i*gw/(vals.length-1),py+gh-(v/max)*gh]),line=a=>a.map((p,i)=>(i?'L':'M')+p[0]+' '+p[1]).join(' ');const target=$('#financeChart');if(target)target.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Live monthly WATAGACHI sales trend"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#4aa7b3" stop-opacity=".22"/><stop offset="1" stop-color="#4aa7b3" stop-opacity="0"/></linearGradient></defs>${[0,.33,.66,1].map(y=>`<line x1="${px}" y1="${py+gh*y}" x2="${W-px}" y2="${py+gh*y}" class="chart-grid"/>`).join('')}<path d="${line(pts)} L ${pts.at(-1)[0]} ${H-py} L ${pts[0][0]} ${H-py} Z" class="chart-area"/><path d="${line(pts)}" class="chart-line"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3.5" class="chart-dot"/><text x="${p[0]}" y="${H-1}" text-anchor="middle" class="chart-label">${months[i].label}</text>`).join('')}</svg>`;};
